window.__votdWeek && window.__votdWeek({"week":"2027-10-18","reading":"1 and 2 Timothy; Titus; Philemon","days":[{"d":"2027-10-18","ref":"1 Timothy 2:8","b":"1 Timothy","c":2,"v":8,"he":"לָכֵן רְצוֹנִי שֶׁיִּתְפַּלֲלוּ הָאֲנָשִׁים בְּכׇל־מָקוֹם וְיִשְׂאוּ יְדֵיהֶם קֹדֶשׁ בְּלִי־רֹגֶז וּמְזִמּוֹת׃","en":"I will therefore that men pray every where, lifting up holy hands, without wrath and doubting."},{"d":"2027-10-19","ref":"1 Timothy 4:3","b":"1 Timothy","c":4,"v":3,"he":"אֹסְרִים לָקַחַת אִשָּׁה וּמֹנְעִים מִמִּינֵי מַאֲכׇל אֲשֶׁר בְּרָאָם הָאֱלֹהִים שֶׁיֹּאכְלוּם בְּתוֹדָה הַמַּאֲמִינִים וְיֹדְעֵי הָאֱמֶת׃","en":"Forbidding to marry, and commanding to abstain from meats, which God hath created to be received with thanksgiving of them which believe and know the truth."},{"d":"2027-10-20","ref":"1 Timothy 5:8","b":"1 Timothy","c":5,"v":8,"he":"וַאֲשֶׁר לֹא יְכַלְכֵּל אֶת־קְרוֹבָיו וְעַל־כֻּלָּם אֶת־בְּנֵי בֵיתוֹ כָּפַר בָּאֱמוּנָה וְרַע הוּא מֵאֲשֶׁר אֵינֶנּוּ מַאֲמִין׃","en":"But if any provide not for his own, and specially for those of his own house, he hath denied the faith, and is worse than an infidel."},{"d":"2027-10-21","ref":"1 Timothy 5:18","b":"1 Timothy","c":5,"v":18,"he":"כִּי־הַכָּתוּב אֹמֵר לֹא־תַחְסֹם שׁוֹר בְּדִישׁוֹ וְנֶאֱמַר רָאוּי הַפֹּעֵל לִשְׂכָרוֹ׃","en":"For the scripture saith, Thou shalt not muzzle the ox that treadeth out the corn. And, The labourer is worthy of his reward."},{"d":"2027-10-22","ref":"2 Timothy 3:15","b":"2 Timothy","c":3,"v":15,"he":"וּמִנְּעוּרֶיךָ יָדַעְתָּ אֶת־כִּתְבֵי הַקֹּדֶשׁ הַיְּכֹלִים לְהַחְכִּימְךָ לַיְשׁוּעָה עַל־יְדֵי הָאֱמוּנָה בַּמָּשִׁיחַ יֵשׁוּעַ׃","en":"And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus."},{"d":"2027-10-23","ref":"2 Timothy 3:16","b":"2 Timothy","c":3,"v":16,"he":"כִּי כׇל־הַכָּתוּב נִכְתָּב בְּרוּחַ אֱלֹהִים וּמוֹעִיל לְהוֹרֹת וּלְהוֹכִיחַ וּלְיַשֵּׁר וּלְהַדְרִיךְ בְּמַעְגְּלֵי צֶדֶק׃","en":"All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:"},{"d":"2027-10-24","ref":"Titus 1:14","b":"Titus","c":1,"v":14,"he":"וְלֹא יָשִׂימוּ לֵב אֶל־הַגָּדוֹת הַיְּהוּדִים וְאֶל־מִצְוֹת הָאֲנָשִׁים הַסָּרִים מִן־הָאֱמֶת׃","en":"Not giving heed to Jewish fables, and commandments of men, that turn from the truth."}]});
